public final class ExportFile implements AutoCloseable {
    private static final Cleaner CLEANER = Cleaner.create();

    // Trạng thái cần dọn tách riêng, không trỏ ngược ExportFile
    private record Deleter(Path path) implements Runnable {
        public void run() {
            try { Files.deleteIfExists(path); } catch (IOException ignored) { }
        }
    }

    private final Path path;
    private final byte[] buffer = new byte[64 * 1024];
    private final Cleaner.Cleanable cleanable;

    public ExportFile(Path dir) throws IOException {
        this.path = Files.createTempFile(dir, "export-", ".csv");
        this.cleanable = CLEANER.register(this, new Deleter(path));
    }

    @Override
    public void close() { cleanable.clean(); }
}

// Cách dùng chính: try (var file = new ExportFile(dir)) { ... }
// Chạy lại không close(): created=20000 tempFilesLeft=1 heapAfterGC=4 MB
